// run
package main

import (
	"fmt"
	"runtime"
	"sync"
)

func main() {
	// one processor, so nothing else can run until a spinner is taken off it
	prev := runtime.GOMAXPROCS(1)
	defer runtime.GOMAXPROCS(prev)

	var wg sync.WaitGroup
	stop := false
	spun := 0
	// A goroutine whose loop contains no function call must still be
	// preempted so the rest of the program can run.
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n := 0
			// no call, no channel operation, no allocation: only asynchronous
			// preemption can take this goroutine off the scheduler
			for !stop {
				n++
			}
			spun += n % 3
		}()
	}
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func(k int) {
			defer wg.Done()
			total := 0
			for j := 0; j < 20000; j++ {
				total += j
			}
			spun += total % 7
		}(i)
	}
	runtime.GC()
	stop = true
	wg.Wait()
	fmt.Println("all goroutines finished:", spun >= 0)
	fmt.Println("goroutines cleaned up:", runtime.NumGoroutine() <= 2)
}

