// run
package main

import (
	"embed"
	"fmt"
	"io/fs"
)

//go:embed assets
var plain embed.FS

//go:embed all:assets
var everything embed.FS

func names(f embed.FS) []string {
	var out []string
	fs.WalkDir(f, "assets", func(p string, d fs.DirEntry, err error) error {
		if !d.IsDir() {
			out = append(out, p)
		}
		return nil
	})
	return out
}

func main() {
	// The default pattern skips names beginning with `.` or `_`; the `all:`
	// prefix keeps them.
	fmt.Println("plain:", names(plain))
	fmt.Println("all:  ", names(everything))
	_, err := plain.ReadFile("assets/_hidden.txt")
	fmt.Println("plain hides underscore:", err != nil)
	b, err := everything.ReadFile("assets/_hidden.txt")
	fmt.Printf("all reads it: %q %v\n", string(b), err)
	b, err = everything.ReadFile("assets/.dotfile")
	fmt.Printf("all reads dotfiles: %q %v\n", string(b), err)
}

