// run
package main

import (
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"sort"
)

//go:embed assets/hello.txt
var hello string

//go:embed assets/hello.txt
var helloBytes []byte

//go:embed assets
var assets embed.FS

func main() {
	fmt.Printf("%q %d\n", hello, len(helloBytes))
	b, err := assets.ReadFile("assets/hello.txt")
	fmt.Printf("%q %v\n", string(b), err)
	_, err = assets.ReadFile("assets/missing.txt")
	fmt.Println(err != nil)
	entries, err := assets.ReadDir("assets")
	fmt.Println(err == nil, len(entries))
	var names []string
	for _, e := range entries {
		names = append(names, fmt.Sprintf("%s:%v", e.Name(), e.IsDir()))
	}
	sort.Strings(names)
	fmt.Println(names)
	var walked []string
	fs.WalkDir(assets, "assets", func(p string, d fs.DirEntry, err error) error {
		walked = append(walked, fmt.Sprintf("%s/%v", p, d.IsDir()))
		return nil
	})
	fmt.Println(walked)
	var f fs.FS = assets
	file, err := f.Open("assets/hello.txt")
	fmt.Println(err == nil)
	info, _ := file.Stat()
	fmt.Println(info.Name(), info.Size(), info.IsDir())
	for _, p := range []string{".", "a/b", "/a", "a/", "a//b", "a/../b", "./a", "..", "a/./b", ""} {
		fmt.Printf("ValidPath(%q)=%v\n", p, fs.ValidPath(p))
	}

	// embed.FS satisfies the io/fs interfaces
	var rdf fs.ReadDirFS = assets
	de, err := rdf.ReadDir("assets")
	fmt.Println("ReadDirFS:", err == nil, len(de))
	var rff fs.ReadFileFS = assets
	data, err := rff.ReadFile("assets/hello.txt")
	fmt.Printf("ReadFileFS: %q %v\n", string(data), err)

	var fi fs.FileInfo = info
	fmt.Println("FileInfo:", fi.Name(), fi.Size(), fi.IsDir())

	_, err = assets.Open("assets/nope.txt")
	fmt.Println("ErrNotExist:", errors.Is(err, fs.ErrNotExist))

	// returning SkipDir from WalkDir skips the rest of that directory
	var pruned []string
	fs.WalkDir(assets, "assets", func(p string, d fs.DirEntry, err error) error {
		if d.IsDir() && p != "assets" {
			return fs.SkipDir
		}
		pruned = append(pruned, p)
		return nil
	})
	fmt.Println("SkipDir:", pruned)
}

