// run
package main

import (
	"embed"
	"fmt"
	"io/fs"
	"sort"
)

//go:embed web/tpl/index.tpl
var index string

//go:embed web/tpl/index.tpl
var indexBytes []byte

// one directive may carry several patterns
//go:embed web/static/css web/tpl
var site embed.FS

//go:embed web
var whole embed.FS

func names(f embed.FS, root string) []string {
	var out []string
	fs.WalkDir(f, root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			out = append(out, p)
		}
		return nil
	})
	sort.Strings(out)
	return out
}

func main() {
	fmt.Printf("%q %d %v\n", index, len(indexBytes), string(indexBytes) == index)
	fmt.Println("two patterns:", names(site, "web"))
	fmt.Println("whole tree:  ", names(whole, "web"))

	// io/fs helpers work against any FS, not just the concrete type
	b, err := fs.ReadFile(whole, "web/static/css/site.css")
	fmt.Printf("fs.ReadFile: %q %v\n", string(b), err)

	entries, err := fs.ReadDir(whole, "web")
	fmt.Print("fs.ReadDir: ", err == nil, " ")
	for _, e := range entries {
		fmt.Print(e.Name(), "/", e.IsDir(), " ")
	}
	fmt.Println()

	sub, err := fs.Sub(whole, "web/tpl")
	fmt.Println("fs.Sub:", err == nil)
	b, err = fs.ReadFile(sub, "index.tpl")
	fmt.Printf("through Sub: %q %v\n", string(b), err)

	matches, err := fs.Glob(whole, "web/*")
	fmt.Println("fs.Glob:", matches, err)

	// a missing path reports fs.ErrNotExist through the FS interface
	_, err = fs.ReadFile(whole, "web/nope")
	fmt.Println("missing:", err != nil)
}

